// # a row stored through a subscript is a store into the row element, as an
// # append is: a literal row stores its values, a list moved in links, an
// # empty list takes the row element, a typed list decides it
// def subscript_row_pos() -> None:
//     g = [[1], [2]]  # tpyc: type(Array[list[int64], 2])
//     g[0] = [wide(), 3]  # tpyc: ok
//     m = [[1], [2]]  # tpyc: type(Array[list[int64], 2])
//     other = [5]  # tpyc: type(list[int64])
//     other.append(wide())  # tpyc: ok
//     m[1] = other  # tpyc: ok
//     k = [[1], [2]]  # tpyc: type(Array[list[int64], 2])
//     k[0] = []  # tpyc: ok
//     k[0].append(wide())  # tpyc: ok
//     r: list[int64] = [4]
//     t = [[1], [2]]  # tpyc: type(Array[list[int64], 2])
//     t[1] = r  # tpyc: ok
//     print("subscript_row:", g, m, k, t)
void subscript_row_pos() {
    std::array<std::vector<int64_t>, 2> g = {{{1}, {2}}};
    ::tpy::__setitem__(g, 0, std::vector<int64_t>{::tpyapp::main::wide(), 3});
    std::array<std::vector<int64_t>, 2> m = {{{1}, {2}}};
    std::vector<int64_t> other = {5};
    other.push_back(::tpyapp::main::wide());
    ::tpy::__setitem__(m, 1, std::move(other));
    std::array<std::vector<int64_t>, 2> k = {{{1}, {2}}};
    ::tpy::__setitem__(k, 0, std::vector<int64_t>{});
    ::tpy::__getitem__(k, 0).push_back(::tpyapp::main::wide());
    std::vector<int64_t> r = {4};
    std::array<std::vector<int64_t>, 2> t = {{{1}, {2}}};
    ::tpy::__setitem__(t, 1, std::move(r));
    std::cout << "subscript_row:" << " " << ::tpy::ListPrinter(g) << " " << ::tpy::ListPrinter(m) << " " << ::tpy::ListPrinter(k) << " " << ::tpy::ListPrinter(t) << "\n" << ::tpy::check_signals;
}

